#!/usr/bin/env python3
"""Generate the self-contained English developer handover from actual resources."""
from pathlib import Path
import argparse, hashlib, json, html
R=Path(__file__).resolve().parents[2]
c=json.loads((R/'campaign/content/campaign.json').read_text())
m=json.loads((R/'campaign/assets/music/manifest.json').read_text())
v=json.loads((R/'campaign/validation-summary.json').read_text())
prose=[p for s in c['scenes'] for p in s['paragraphs']]
prose.extend(p for s in c['scenes'] for variant in s.get('variants',[]) for p in variant['paragraphs'])
for e in c['endings']:
    prose.extend(e['paragraphs'])
    for ep in e.get('epilogues',[]):prose.extend(ep['paragraphs'])
prose.extend(s['survey']['text'] for s in c['systems'] if 'survey' in s)
words=sum(len(p.split()) for p in set(prose))
eps={json.dumps(ep,sort_keys=True) for e in c['endings'] for ep in e.get('epilogues',[])}
choices=sum(len(s['choices']) for s in c['scenes'])
surveys=sum('survey' in s for s in c['systems'])
characters=''.join(f'<article><small>{html.escape(x["species"])}</small><h3>{html.escape(x["name"])}</h3><p>{html.escape(x["role"])}</p></article>' for x in c['characters'])
tracks=''.join(f'<tr><td>{html.escape(t["title"])}</td><td>{t["bpm"]}</td><td>{t["duration"]:.0f}s</td><td><code>{t["id"]}</code></td></tr>' for t in m['tracks'])
def esc(value):
    return html.escape(str(value))

def status(report):
    return 'Passed' if report.get('passed') is True else 'Failed' if report.get('passed') is False else 'Not recorded'

def browser_label(report):
    browser=report.get('browser')
    if isinstance(browser,dict):
        return ' '.join(str(browser.get(key,'')) for key in ('name','version')).strip() or 'Not recorded'
    return f'Chromium / Chrome {browser}' if browser else 'Not recorded'

def rows_table(headers,rows):
    if not rows:return '<p class="muted">No results recorded in the validation summary.</p>'
    headings=''.join(f'<th>{esc(value)}</th>' for value in headers)
    cells=''.join('<tr>'+''.join(f'<td>{esc(value)}</td>' for value in row)+'</tr>' for row in rows)
    return f'<div class="table"><table><tr>{headings}</tr>{cells}</table></div>'

def bullets(values):
    return '<ul>'+''.join(f'<li>{esc(value)}</li>' for value in values)+'</ul>' if values else ''

recorded=v.get('campaign',{})
browser_reports=v.get('browsers') or ([v['browser']] if v.get('browser') else [])
browser_rows=[]
route_rows=[]
for report in browser_reports:
    assets=report.get('assets',{})
    browser_rows.append((browser_label(report),status(report),len(report.get('routes',[])),
        f'{len(assets.get("portraits",[]))} portraits / {len(assets.get("decoded",[]))} decoded tracks',
        'Checked' if report.get('mobile') is True else 'Not recorded'))
    for route in report.get('routes',[]):
        route_rows.append((browser_label(report),route['ending'],route['actions'],route['day'],route['systems']))
browser_table=rows_table(['Story browser','Result','Final routes','Asset checks','Narrow layout'],browser_rows)
routes=rows_table(['Story browser','Ending','Ordinary actions','Ending day','Visited systems'],route_rows)
unit=v.get('unitTests',{})
validation_items=[]
if unit:
    validation_items.append(f'Campaign unit tests: {unit.get("passed","not recorded")} passed; {unit.get("failed","not recorded")} failed.')
    if unit.get('failed')==0:
        validation_items.append(f'Content tests cover ordinary-action access to all {recorded.get("scenes","recorded")} scenes, completion of all {recorded.get("quests","recorded")} quests, and one-time rewards at all {recorded.get("surveys","recorded")} surface destinations. The three endings remain reachable after late arrival and resource exhaustion.')
        validation_items.append('Each principal Act-II lead opens Act III. Native engagement receipt fixtures check both noncombat recovery and a fresh battle retry after defeat or retreat; they do not substitute for a physical native combat test.')
if v.get('legacyCompatibility'):
    legacy=v['legacyCompatibility']
    validation_items.append(f'Pre-revision save compatibility: {legacy.get("loaded","not recorded")} of {legacy.get("checkpoints","not recorded")} authentic checkpoints loaded.')
if v.get('independentReview'):
    review=v['independentReview']
    validation_items.append(f'Independent review: {review.get("passes","not recorded")} passes; {review.get("remainingConfirmedFindings","not recorded")} remaining confirmed findings. This is a code/content review, not independent human literary assessment.')
validation_list=bullets(validation_items)
supporting_rows=[]
supporting_details=[]
for key,title in [('recovery','Save and interface recovery'),('progression','Equipment, hulls and crew'),
                  ('surfaces','Physical surface modes'),('parentIntegration','Campaign encounter integration')]:
    report=v.get(key)
    if not isinstance(report,dict):continue
    checks=report.get('checks',report.get('steps',[]))
    supporting_rows.append((title,status(report),browser_label(report),len(report.get('errors',[]))))
    details=bullets(checks)
    if report.get('modes'):
        details+=rows_table(['Completed mode','Control legs','Active seconds'],[(mode['mode'],mode.get('legs','—'),
            f'{mode["simulationSeconds"]:.2f}' if 'simulationSeconds' in mode else '—') for mode in report['modes']])
    if report.get('results'):
        details+=bullets([f'Physical receipts recorded: {len(report["results"])}; outcomes: '+', '.join(result.get('outcome','unknown') for result in report['results'])+'.'])
    if report.get('failure'):details+=f'<p>{esc(report["failure"])}</p>'
    if details:supporting_details.append(f'<details><summary>{esc(title)} — recorded checks</summary>{details}</details>')
supporting_table=rows_table(['Suite','Result','Browser','Recorded errors'],supporting_rows)
supporting_details=''.join(supporting_details)
progression_matrix=rows_table(['Progression browser','Result','Native hull','Physical native frames'],[(browser_label(r),status(r),r.get('native',{}).get('ship','—'),r.get('native',{}).get('receipt',{}).get('frames','—')) for r in v.get('progressionBrowsers',[])])
limitations=bullets(v.get('limitations',[]))
validation_scope=esc(v.get('scope','Local development evidence only.'))
validation_date=esc(v.get('date','Date not recorded'))
historical=json.loads((R/'campaign/gameplay-validation.json').read_text())
native=historical.get('nativeCombat',{})
native_sources=['campaign/src/combat.mjs','rust/uqm-engine-original/campaign.rs','campaign/native-hooks.patch']
source_match=all(historical.get('sourceHashes',{}).get(path)==hashlib.sha256((R/path).read_bytes()).hexdigest() for path in native_sources)
build_hashes=native.get('build',{})
build_present=bool(build_hashes) and all((R/'.tools/afterlight-dist/combat'/path).exists() for path in build_hashes)
build_match=build_present and all(hashlib.sha256((R/'.tools/afterlight-dist/combat'/path).read_bytes()).hexdigest()==digest for path,digest in build_hashes.items())
native_note=f'Historical native evidence dated {historical.get("testedAt","not recorded")} records {len(native.get("shipMatrix",[]))} player-hull launches in Chromium / Chrome {native.get("browser","not recorded")}, plus the saved victory, defeat and withdrawal receipts. Its native-combat result is {status(native).lower()}.'
native_note+=' The native adapter, Rust campaign bridge and regeneration patch still match the recorded source hashes.' if source_match else ' The current native source hashes do not all match that historical record; it must not be treated as current verification.'
if build_present:native_note+=' The packaged native JavaScript, WebAssembly and host also match the historical build hashes.' if build_match else ' The packaged native build differs from the historical fingerprints.'
else:native_note+=' No packaged native build was available for fingerprint comparison when this document was generated.'
native_note=esc(native_note)
body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Afterlight Accord — developer handover</title><style>
:root{{--bg:#08151e;--panel:#102631;--ink:#e8e5d6;--muted:#a9bec6;--gold:#e5bc79;--line:#31505c}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 system-ui,sans-serif}}a{{color:#9de0d7}}.wrap{{max-width:1120px;margin:auto;padding:0 36px}}header{{padding:72px 0 56px;background:radial-gradient(ellipse at 90% 0,#425959,transparent 55%),linear-gradient(125deg,#132a37,#07121a);border-bottom:1px solid var(--line)}}.kicker,small{{display:block;color:var(--gold);letter-spacing:.14em;text-transform:uppercase;font-size:11px}}h1,h2,h3{{font-family:Georgia,serif;font-weight:400;line-height:1.16}}h1{{font-size:clamp(42px,7vw,80px);letter-spacing:-.045em;margin:20px 0}}h2{{font-size:34px;margin:0 0 22px}}h3{{font-size:22px;margin:8px 0 14px}}.dek{{max-width:740px;font-size:20px;color:#c6d6da}}.meta{{display:flex;gap:14px;flex-wrap:wrap;margin-top:32px}}.pill{{border:1px solid #52717b;border-radius:99px;padding:6px 14px;font-size:12px}}nav{{display:flex;flex-wrap:wrap;gap:12px 22px;padding:22px 0;border-bottom:1px solid var(--line)}}nav a{{margin-right:0;white-space:nowrap;font-size:13px}}section{{padding:48px 0;border-bottom:1px solid var(--line)}}p{{margin:0 0 18px}}.muted{{color:var(--muted)}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}}.grid article{{padding:22px;background:var(--panel);border-top:2px solid var(--gold)}}.grid p{{color:var(--muted);font-size:14px;margin:0}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:28px 0}}.stat{{border-left:2px solid var(--gold);padding-left:16px;font-size:13px;color:var(--muted)}}.stat strong{{display:block;font:34px Georgia,serif;color:var(--ink)}}.note{{padding:20px 24px;border-left:3px solid var(--gold);background:var(--panel);margin:25px 0}}.split>* , .grid>*{{min-width:0}}.split{{display:grid;grid-template-columns:1fr 1fr;gap:32px}}code{{font-size:13px;overflow-wrap:anywhere}}pre{{padding:20px;background:#040d14;border:1px solid var(--line);overflow:auto;line-height:1.55}}table{{border-collapse:collapse;width:100%;font-size:14px}}th,td{{text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:12px 10px}}th{{color:var(--gold);font-weight:500}}.table{{overflow-x:auto}}li{{margin-bottom:9px}}details{{padding:20px;background:var(--panel);margin:22px 0}}summary{{cursor:pointer;color:var(--gold);font-weight:600}}details p{{margin-top:18px}}footer{{padding:36px 0 70px;color:var(--muted);font-size:13px}}@media(max-width:700px){{.wrap{{padding:0 20px}}header{{padding:40px 0}}.grid,.split{{grid-template-columns:1fr}}.stats{{grid-template-columns:1fr 1fr}}section{{padding:32px 0}}h2{{font-size:29px}}}}@media print{{body{{background:white;color:#14212a;font-size:11px}}header{{background:white;padding:20px 0}}.wrap{{max-width:none}}.grid article,.note,details{{background:#f2f5f4}}.muted,.grid p,small,.kicker{{color:#455960}}a{{color:#185761}}section{{break-inside:avoid;padding:20px 0}}pre{{background:#edf1f2;color:#14212a}}nav{{display:none}}h1{{font-size:44px}}}}
</style></head><body><header><div class="wrap"><span class="kicker">UQM · Original fan continuation · Developer handover</span><h1>The Afterlight Accord</h1><p class="dek">A complete new branching expedition in the Far Reach, with authored consequences, original illustrations and music, physical surface exploration, and genuine Rust UQM combat.</p><div class="meta"><span class="pill">Branch: codex/uqm-new-campaign</span><span class="pill">Validation record: {validation_date}</span><span class="pill">English campaign</span></div></div></header><div class="wrap"><nav><a href="#play">Play</a><a href="#scope">Scope</a><a href="#architecture">Architecture</a><a href="#validation">Validation</a><a href="#resources">Resources</a><a href="#handoff">Handoff</a></nav>
<section id="play"><small>01 / Start here</small><h2>A ship with one extra chair.</h2><p>Seven years after the Sa-Matra’s defeat, the Wayfarer surveys settlements beyond the old Hierarchy frontier. An abandoned planetary shield requests a passenger berth. The caller is new, alive, and difficult to fit into a reconstruction system that already knows how every request should be answered.</p><p>Original victories remain meaningful. The new story grows from the unfinished work of liberation, with humor, material constraints and people whose interests do not neatly agree.</p><div class="split"><div><h3>Local preview</h3><pre>npm run build:afterlight\nnpm run start:afterlight</pre><p><a href="http://127.0.0.1:10002/">Open the local game →</a></p><p class="muted">Use the pinned toolchains described in the repository README. Once native combat is built, <code>bash scripts/build-afterlight.sh --ui-only</code> repackages narrative and interface changes quickly.</p></div><div><h3>What the player gets</h3><p>Star chart, partial resupply, complete transmissions by default with optional short passages, portraits, musical themes, evidence and quest journal, full conversation log, protected saves with backup recovery and import/export, three surface modes, equipment and hull progression, space battles and three authored endings.</p><p class="muted">Reading is untimed. Travel and certain decisions advance days. The journal exposes commitments: delay can consume reserves, require repairs or turn a free hull grant into a paid replacement. Resource exhaustion, damaged relationships, retreat and defeat retain explicit recovery paths.</p></div></div></section>
<section id="revision"><small>Revision / Playability review</small><h2>Discoveries now change the voyage.</h2><p>The review found repeated surface tasks, little equipment progression, fragile saves, unearned memories and choices whose aftermath ignored the decision. This revision addresses those issues in the playable campaign.</p><div class="grid"><article><h3>Investigate and build</h3><p>Three evidence-based investigations, useful field discoveries, six upgrades, five attainable hulls and two completed destination questlines connect exploration to capability.</p></article><article><h3>Different ways to act</h3><p>Mapping, recovery shuttles and relay expeditions have different physical objectives. Each political ending has its own three-stage operation, with remembered engineering and personal consequences.</p></article><article><h3>Keep the voyage coherent</h3><p>Announced deadlines have recovery routes; battle retries preserve rewards; crew reserves and delivered rescues persist. Optional memories, opposing decisions and old-save aftermaths now follow actual history.</p></article></div><p class="muted">The story remains a smaller, predominantly dialogue-led adventure. Shorter prose and clearer agency improve its design; independent players are still needed to judge enjoyment, emotional impact and lasting replay value.</p></section><section id="scope"><small>02 / Delivered scope</small><h2>Four acts. Three futures.</h2><div class="stats"><div class="stat"><strong>{len(c['scenes'])}</strong>authored conversation scenes</div><div class="stat"><strong>{words:,}</strong>unique narrative words</div><div class="stat"><strong>{len(c['systems'])}</strong>charted systems</div><div class="stat"><strong>{len(c['quests'])}</strong>quest threads</div><div class="stat"><strong>{choices}</strong>authored responses</div><div class="stat"><strong>{surveys}</strong>physical survey locations</div><div class="stat"><strong>{len(eps)}</strong>conditional epilogue entries</div><div class="stat"><strong>{sum(t['duration'] for t in m['tracks'])/60:.1f} min</strong>original instrumental score</div></div><p class="muted">Narrative words count unique scene, history-dependent variant, ending, epilogue and survey prose. Repeated epilogues attached to several endings are counted once. This is substantially smaller than the original campaign’s approximately 98,143 dialogue words.</p><div class="grid"><article><small>I / A new passenger</small><h3>Listen before deciding.</h3><p>Meet the Wayfarer’s crew, recover the first Afterlight, and discover the cost of sustaining a new life.</p></article><article><small>II / Six independent leads</small><h3>Promises acquire weight.</h3><p>A missing passenger, borrowed heat, public records, restitution, an unfinished synthesis and a refusal reveal different parts of the Reach.</p></article><article><small>III / IV</small><h3>Investigate, build, commit.</h3><p>Compare records, test diagnoses, repair wrong turns, reopen Common Crossing and an outbound receiver, then build a distinct final operation whose costs remain visible in the ending.</p></article></div><details><summary>Plot architecture — major spoilers</summary><p>The reconstruction network creates provisional Afterlight minds to forecast decisions, then discards versions that refuse. Sera authorized predictive assent without understanding the lives being erased. Discovery does not make her previous authority legitimate or her relief work worthless.</p><p>The pluralist accord requires actual clocks, public witnesses, independent capacity and a prepared harbor, followed by a buffer, staged timing and a live-refusal test. The mandate isolates its control panel, tests failover and assigns the breaker authority. Partition chooses where people can go, preserves a bridge and witnesses the final separation. Each settlement has its own operation, repairable mistakes, selectable terms and conditional personal epilogues. The game does not reduce this to a universal morality score.</p><p>The story bible records the full four-act outline, faction motives, reveal timing, clue routes, canonical boundaries and unresolved mysteries.</p></details><h3>Ten principal characters</h3><div class="grid">{characters}</div></section>
<section id="architecture"><small>03 / Implementation</small><h2>Authored data, deterministic rules, real encounters.</h2><div class="table"><table><tr><th>Layer</th><th>Implementation</th><th>Contract</th></tr><tr><td>Narrative</td><td><code>campaign/content/campaign.json</code></td><td>Scenes, choices, requirements, resources, discoveries, world events and endings. No runtime story generation.</td></tr><tr><td>Campaign state</td><td><code>campaign/src/state.mjs</code></td><td>Immutable atomic actions, strict save validation, one-time rewards, explicit pending encounters and matching receipts.</td></tr><tr><td>Presentation</td><td><code>app.mjs</code>, HTML and CSS</td><td>Responsive illustrated interface, full transmissions by default, optional short passages, keyboard choices, accessible buttons and larger text. Failed storage leaves live progress and export available; missing or corrupt primary saves can recover a valid backup.</td></tr><tr><td>Surface</td><td><code>lander.mjs</code>, Canvas</td><td>Three seeded modes: mapping, one-at-a-time recovery deliveries and ordered relay windows. Fixed-step movement, hazards, battery, ore and return-to-pad completion. Briefing, explicit pause and focus loss preserve battery; secured recovery deliveries survive recall, damage and save/load.</td></tr><tr><td>Outfitting</td><td>Authored upgrades and shipyard offers</td><td>{len(c.get('upgrades',[]))} upgrades and {len(c.get('shipyard',[]))} additional hulls unlocked by research, trust, work or purchases. Hull switches transfer surviving crew and retain overflow reserves without healing or duplication.</td></tr><tr><td>Combat</td><td>Original UQM Rust → WebAssembly</td><td>Native hulls, weapons, specials, AI, collision and crew. An isolated iframe reports a real victory, defeat or withdrawal.</td></tr><tr><td>Music</td><td>Local Ogg + Web Audio</td><td>15 original cues with crossfades, user-gesture activation, bounded cache and a music toggle.</td></tr><tr><td>Build</td><td><code>scripts/build-afterlight.sh</code></td><td>Clean portable output, SHA-256 file manifest, no stale build assets. Refuses to replace unrelated output directories.</td></tr></table></div><p class="note">The campaign shell and new surface game are JavaScript. Space combat uses the existing Rust translation and preserves original UQM pixel-art ships and sound effects. This is not a claim that the entire campaign is Rust, that all ships were redrawn, or that the original lander was ported into this new interface.</p><h3>Hosting</h3><p>Serve <code>.tools/afterlight-dist/</code> over HTTPS with <code>Cross-Origin-Opener-Policy: same-origin</code> and <code>Cross-Origin-Embedder-Policy: require-corp</code>. Serve <code>.mjs</code> as JavaScript and <code>.wasm</code> as WebAssembly. The included Rust server already provides the necessary behavior. Localhost is sufficient for local play. No campaign server, AI subscription, telemetry or remote media service is required. For a downloadable release from a clean committed checkout, run <code>bash scripts/package-afterlight-release.sh</code>. The resulting ZIP includes an exact corresponding source archive, revision, file hashes and hosting instructions.</p><p>Use a dedicated path or origin for preview. The existing Original/HD launchers and multiplayer system remain separate. Deployment and a merge to main have not been requested.</p></section>
<section id="validation"><small>04 / Evidence</small><h2>Test what the player actually does.</h2><p>{validation_scope}</p><p>The tables below are generated from <code>campaign/validation-summary.json</code>, dated {validation_date}. A passing story-browser run replays all recorded final routes from a new expedition through visible controls, then compares the complete result with the ordinary-action state model. It does not inject flags, resources or ending states. Missing checks are not reported as successes.</p>{browser_table}{routes}{validation_list}<h3>Recovery, progression and physical encounters</h3>{supporting_table}{supporting_details}<h3>Acquired hull and partial rescue across browsers</h3>{progression_matrix}<p class="note">{native_note} This historical 25-hull matrix is separate from the newer story-browser runs and the acquired-hull progression check. It does not establish that every native hull, sound or battle outcome was retested in each story browser. The earlier surface result covers the previous lander; the current surface reports above describe the revised modes.</p><h3>Reproduce the checks</h3><pre>npm run test:afterlight\nnpm run test:afterlight:browser\nnpm run test:afterlight:recovery\nnode campaign/tests/progression-browser.mjs\nnode campaign/tests/integration-encounters.mjs\nnode campaign/tests/combat-browser.mjs\nnode campaign/tests/lander-browser.mjs\npython3 campaign/tools/verify-audio.py</pre><p>Install the locked browser runtimes with <code>npx playwright install chromium firefox webkit</code>. The story suite accepts <code>AFTERLIGHT_BROWSER=firefox npm run test:afterlight:browser</code> and <code>AFTERLIGHT_BROWSER=webkit npm run test:afterlight:browser</code>. Chromium is the default; <code>CHROME_BIN</code> selects an installed Chrome. The progression suite accepts the same browser selector. Recovery and the broader native encounter suite use Chromium.</p><p class="muted">Tracked evidence: <code>campaign/gameplay-validation.json</code> and <code>campaign/validation-summary.json</code>. Tests generate screenshots and receipts under <code>test-results/</code>. CI is defined in <code>.github/workflows/afterlight.yml</code>; local success does not imply hosted CI has finished.</p><h3>Recorded limitations</h3>{limitations}</section>
<section id="resources"><small>05 / Resource inventory</small><h2>Everything needed at runtime is local.</h2><p>Ten original high-resolution character portraits, one cover illustration, fifteen synthesized stereo music files, fifteen editable MIDI scores, score metadata, a reproducible composer, authored narrative content and procedural chart/surface visuals are included. Native UQM ship resources retain their original notices.</p><div class="table"><table><tr><th>Composition</th><th>BPM</th><th>Length</th><th>Resource ID</th></tr>{tracks}</table></div><h3>Provenance and editability</h3><p>The new illustrations were generated from text with OpenAI’s built-in image tool. <code>campaign/assets/art-manifest.json</code> records generation mode, art direction, briefs, dimensions and hashes. The music uses explicitly authored motifs and arrangements rendered by <code>campaign/tools/compose.py</code>; it contains no sampled recordings. The editable scores and generator are delivered alongside the recordings.</p><p>New code and writing are GPL-2.0-or-later. New generated art and synthesized music are CC BY-SA 4.0 to the extent rights are held. Existing UQM code and assets keep their existing terms. See <code>campaign/CREDITS.html</code>. No recorded voice performances are included.</p></section>
<section id="handoff"><small>06 / Continue development</small><h2>A complete campaign, ready for human review.</h2><p>Keep the story schema and state tests together. For any plot edit, validate references and replay affected ending and recovery routes. Native Rust hooks are documented and preserved in <code>campaign/native-hooks.patch</code>; apply them to a staging translation rather than overwriting the working engine.</p><div class="split"><div><h3>Reading order</h3><ol><li><code>campaign/README.md</code> — play, build and controls</li><li><code>docs/afterlight-story-bible.md</code> — complete narrative and spoiler notes</li><li><code>campaign/SCHEMA.md</code> — data and save contracts</li><li><code>campaign/NATIVE-COMBAT.md</code> — combat and surface integration</li><li><code>docs/afterlight-original-study-*.md</code> — original-campaign research and limits</li></ol></div><div><h3>Before a public release</h3><p>Invite independent players to complete several routes without a guide. Review pacing, humor, emotional payoffs, music fatigue, difficulty and accessibility. Extend the recorded browser matrix to longer sessions, actual mobile devices and assistive technologies. Playwright WebKit evidence is not a claim of testing every Safari release or device. Mobile reading and surface controls are provided; native battles still need a keyboard.</p><p>A test suite establishes functional evidence. It cannot establish that a new story equals or exceeds Star Control II. That judgment belongs to readers and players.</p></div></div><p><a href="https://github.com/vcorem/uqm-3do-web/tree/codex/uqm-new-campaign">Open the campaign branch on GitHub →</a></p></section><footer>Self-contained English handover · The Afterlight Accord project · No external fonts, scripts or assets are required to read this document.</footer></div></body></html>'''
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--output',type=Path,default=R/'docs/afterlight-handover.html')
args=parser.parse_args()
args.output.write_text(body)
print(f'Handover: {words:,} unique narrative words; {choices} responses; {len(eps)} conditional epilogues.')
